using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Creezio.Switcher;

internal static class TransferTests
{
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    private static void Refused(Action action){try{action();}catch(InvalidOperationException){return;}throw new Exception("Expected refusal");}
    private sealed class Backend:ITransferBackend
    {
        internal string Account="target-account",FailCopy,Busy,Changed,MissingTarget;internal bool Visible=true,LostArchive,AssignmentFailure;
        internal int Copies,Archives,Assignments;internal List<string> Events=new List<string>();internal HashSet<string> Archived=new HashSet<string>();internal Dictionary<string,ThreadCopyRecord> Receipts=new Dictionary<string,ThreadCopyRecord>();
        public string Identity(string instance){return instance=="source"?"source-account":Account;}
        public Task<TransferProject[]> Projects(string instance,CancellationToken token){return Task.FromResult(new[]{new TransferProject{Id="project",Name="Example",Roots=new[]{Path.GetTempPath()},Threads=new[]{new CopyThreadChoice{Id="one",Title="First"},new CopyThreadChoice{Id="two",Title="Second"}}}});}
        public Task<string> Fingerprint(string instance,string thread,bool idle,CancellationToken token){if(thread==MissingTarget||idle&&thread==Busy)throw new InvalidOperationException("not ready");return Task.FromResult(thread==Changed?"changed":"digest-"+thread);}
        public Task<ThreadCopyRecord> Copy(TransferRecord r,TransferItem item,CancellationToken token){Events.Add("copy:"+item.Source);if(item.Source==FailCopy)throw new InvalidOperationException("copy failed");ThreadCopyRecord copy;if(!Receipts.TryGetValue(item.CopyId,out copy)){Copies++;copy=new ThreadCopyRecord{State="completed",TargetThread="target-"+item.Source};Receipts[item.CopyId]=copy;}return Task.FromResult(copy);}
        public Task<string> Project(TransferRecord r,CancellationToken token){return Task.FromResult(Visible?"target-project":null);}
        public Task Assign(TransferRecord r,TransferItem item,CancellationToken token){Assignments++;if(AssignmentFailure)throw new InvalidOperationException("assignment unconfirmed");Events.Add("assign:"+item.Source);return Task.FromResult(0);}
        public Task Archive(string instance,string thread,CancellationToken token){Events.Add("archive:"+thread);Archives++;Archived.Add(thread);if(LostArchive)throw new IOException("reply lost");return Task.FromResult(0);}
        public Task<bool> IsArchived(string instance,string thread,CancellationToken token){return Task.FromResult(Archived.Contains(thread));}
        public Task Open(TransferRecord r,TransferItem item,CancellationToken token){return Task.FromResult(0);}
    }
    private sealed class Fixture
    {
        internal Backend Backend=new Backend();internal Transfers Service;internal TransferRequest Request;internal RelayStore Store;
        internal Fixture(string root,string kind="transfer_project"){Store=new RelayStore(Path.Combine(root,"transfer-"+Guid.NewGuid().ToString("N")));Service=new Transfers(Store,Backend);Request=new TransferRequest{Id=Guid.NewGuid().ToString("N"),Kind=kind,Source="source",Destination="target",Item=kind=="transfer_thread"?"one":"project",Title="Destination"};}
        internal TransferRecord Prepare(){return Service.Prepare(Request,CancellationToken.None).GetAwaiter().GetResult();}
        internal TransferRecord Run(){return Service.Run(Request.Id,CancellationToken.None).GetAwaiter().GetResult();}
    }
    internal static void RunAll(Action<string,Action> check,string root)
    {
        check("transfer prepares without copying or archiving",()=>{var f=new Fixture(root);Assert(f.Prepare().Items.Length==2&&f.Backend.Copies==0&&f.Backend.Archives==0,"prepare wrote destination");});
        check("instance refresh accepts unloaded chats but refuses running attention or unknown states",()=>{Assert(TransferBackend.IdleStatus("idle")&&TransferBackend.IdleStatus("notLoaded"),"unloaded chat blocked");Assert(!TransferBackend.IdleStatus("active")&&!TransferBackend.IdleStatus("needsAttention")&&!TransferBackend.IdleStatus(""),"busy or unknown chat accepted");});
        check("transfer archives only after all copies and memberships verified",()=>{var f=new Fixture(root);f.Prepare();var r=f.Run();Assert(r.State=="completed"&&f.Backend.Copies==2&&f.Backend.Archives==2,"incomplete batch");Assert(f.Backend.Events.IndexOf("archive:one")>f.Backend.Events.IndexOf("assign:two"),"early archive");});
        check("transfer project unavailable in UI blocks copies and archives",()=>{var f=new Fixture(root);f.Prepare();f.Backend.Visible=false;Assert(f.Run().State=="awaiting_codex"&&f.Backend.Copies==0&&f.Backend.Archives==0,"invisible success");f.Backend.Visible=true;Assert(f.Run().State=="completed","resume failed");});
        check("transfer partial copy failure keeps all sources",()=>{var f=new Fixture(root);f.Prepare();f.Backend.FailCopy="two";Refused(()=>f.Run());Assert(f.Backend.Archives==0,"partial batch archived");f.Backend.FailCopy=null;Assert(f.Run().State=="completed"&&f.Backend.Copies==2,"duplicate retry");});
        check("transfer changed source before copy is refused",()=>{var f=new Fixture(root);f.Prepare();f.Backend.Changed="one";Refused(()=>f.Run());Assert(f.Backend.Copies==0&&f.Backend.Archives==0,"changed source imported");});
        check("transfer destination changed before archiving retains sources",()=>{var f=new Fixture(root);f.Prepare();f.Backend.FailCopy="two";Refused(()=>f.Run());f.Backend.FailCopy=null;f.Backend.Changed="target-one";Refused(()=>f.Run());Assert(f.Backend.Archives==0,"changed target ignored");});
        check("transfer busy destination blocks all archiving",()=>{var f=new Fixture(root);f.Prepare();f.Backend.Busy="target-two";Refused(()=>f.Run());Assert(f.Backend.Archives==0,"busy target ignored");});
        check("transfer missing destination blocks all archiving",()=>{var f=new Fixture(root);f.Prepare();f.Backend.FailCopy="two";Refused(()=>f.Run());f.Backend.FailCopy=null;f.Backend.MissingTarget="target-one";Refused(()=>f.Run());Assert(f.Backend.Archives==0,"missing target ignored");});
        check("transfer archive lost response reconciles without new copy",()=>{var f=new Fixture(root,"transfer_thread");f.Prepare();f.Backend.LostArchive=true;try{f.Run();}catch(IOException){}f.Backend.LostArchive=false;Assert(f.Run().State=="completed"&&f.Backend.Archives==1&&f.Backend.Copies==1,"archive replayed");});
        check("transfer completed retry does not mutate continued target",()=>{var f=new Fixture(root);f.Prepare();f.Run();int n=f.Backend.Events.Count;f.Backend.Changed="target-one";Assert(f.Run().State=="completed"&&f.Backend.Events.Count==n,"completed modified");});
        check("transfer identity is pinned across retries",()=>{var f=new Fixture(root);f.Prepare();f.Backend.Account="another";Refused(()=>f.Run());Assert(f.Backend.Copies==0,"account changed");});
        check("transfer operation binds selection and mode",()=>{var f=new Fixture(root);f.Prepare();f.Request.Kind="copy_project";Refused(()=>f.Prepare());});
        check("project clone never archives originals",()=>{var f=new Fixture(root,"copy_project");f.Prepare();Assert(f.Run().State=="completed"&&f.Backend.Copies==2&&f.Backend.Archives==0,"clone archived");});
        check("open project files imports no conversation",()=>{var f=new Fixture(root,"link_project");Assert(f.Prepare().Items.Length==0,"history selected");Assert(f.Run().State=="completed"&&f.Backend.Copies==0&&f.Backend.Archives==0,"history copied");});
        check("unconfirmed membership blocks all source archives",()=>{var f=new Fixture(root);f.Prepare();f.Backend.AssignmentFailure=true;Refused(()=>f.Run());Assert(f.Backend.Archives==0,"unassigned archive");});
        check("membership uses explicit project rather than shared cwd",()=>{var state=Json.Read<object>("{\"thread-project-assignments\":{\"t\":{\"projectKind\":\"local\",\"projectId\":\"other\"}}}");var t=new{id="t",projectId="backend",cwd="same"};Assert(!TransferBackend.Membership(state,Json.Read<object>(Json.Write(t)),"wanted","backend"),"stale backend overrides explicit membership");});
        check("projectless override prevents accidental membership",()=>{Assert(!TransferBackend.Membership(Json.Read<object>("{\"projectless-thread-ids\":[\"t\"]}"),Json.Read<object>("{\"id\":\"t\",\"projectId\":\"b\"}"),"a","b"),"projectless included");});
        check("independent files preserve empty folders and verify hashes",()=>{string source=Path.Combine(root,"files-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(source,"empty"));File.WriteAllText(Path.Combine(source,"hello.txt"),"été");var m=ProjectFiles.Plan(source,source+"-copy",CancellationToken.None);ProjectFiles.Copy(m,()=>{},CancellationToken.None);Assert(m.Completed&&Directory.Exists(Path.Combine(m.Destination,"empty"))&&File.ReadAllText(Path.Combine(m.Destination,"hello.txt"))=="été"&&!File.Exists(Path.Combine(m.Destination,".account-switcher-copy")),"copy incomplete");Assert(ProjectFiles.Map(m,source)==m.Destination,"cwd not mapped");Refused(()=>ProjectFiles.Map(m,Path.GetDirectoryName(source)));});
        check("independent files refuse existing or overlapping destinations",()=>{string source=Path.Combine(root,"paths-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(source);Refused(()=>ProjectFiles.Plan(source,source,CancellationToken.None));Refused(()=>ProjectFiles.Plan(source,Path.Combine(source,"child"),CancellationToken.None));Refused(()=>ProjectFiles.Plan(source,root,CancellationToken.None));});
        check("independent files refuse changed source without overwrite",()=>{string source=Path.Combine(root,"change-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(source);string file=Path.Combine(source,"a");File.WriteAllText(file,"before");var m=ProjectFiles.Plan(source,source+"-copy",CancellationToken.None);File.WriteAllText(file,"after");Refused(()=>ProjectFiles.Copy(m,()=>{},CancellationToken.None));Assert(!Directory.Exists(m.Destination),"destination changed");});
        check("independent files never overwrite destination created by another process",()=>{string source=Path.Combine(root,"race-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"a"),"source");var m=ProjectFiles.Plan(source,source+"-copy",CancellationToken.None);Directory.CreateDirectory(m.Destination);File.WriteAllText(Path.Combine(m.Destination,"a"),"user");Refused(()=>ProjectFiles.Copy(m,()=>{},CancellationToken.None));Assert(File.ReadAllText(Path.Combine(m.Destination,"a"))=="user","user file replaced");});
        check("offline project registration preserves all unrelated state",()=>{string home=Path.Combine(root,"offline-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(home);string path=Path.Combine(home,".codex-global-state.json");File.WriteAllText(path,"{\"other\":{\"keep\":42},\"project-order\":[\"old\"],\"local-projects\":{\"old\":{\"name\":\"Existing\"}}}");string id=Guid.NewGuid().ToString();var p=Json.Read<object>(Json.Write(new{id=id,name="Imported",roots=new[]{new{path=home}}}));OfflineProjects.Register(home,p,()=>true);var data=Json.Read<object>(File.ReadAllText(path));Assert(Convert.ToInt32(Json.Get(Json.Get(data,"other"),"keep"))==42&&Json.Get(Json.Get(data,"local-projects"),"old")!=null&&Json.Get(Json.Get(data,"local-projects"),id)!=null,"existing state lost");string once=File.ReadAllText(path);OfflineProjects.Register(home,p,()=>true);Assert(File.ReadAllText(path)==once,"idempotence changed data");});
        check("offline project registration refuses a running or concurrently changed profile",()=>{string home=Path.Combine(root,"offline-race-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(home);string path=Path.Combine(home,".codex-global-state.json");File.WriteAllText(path,"{}");var p=Json.Read<object>(Json.Write(new{id=Guid.NewGuid().ToString(),name="Imported",roots=new[]{new{path=home}}}));Refused(()=>OfflineProjects.Register(home,p,()=>false));int checks=0;Refused(()=>OfflineProjects.Register(home,p,()=>{checks++;if(checks==2)File.WriteAllText(path,"{\"newer\":true}");return true;}));Assert(File.ReadAllText(path)=="{\"newer\":true}","concurrent state overwritten");});
    }
}
